// spec: .qa/e2e/specs/post-create.md · кейс .qa/tests/post-create/PC-06.md (шаги 2–4) · роли free + user4 (пишется вручную, не генератором)
// @data: идёт в проекте data; окна ролей — iPhone 13 Mini (WebKit), см. iphoneUser в post-helpers.
import { test, expect } from '@playwright/test';
import { saveSession } from '../_shared/session';
import { IPHONE, cleanupPost, deletePostViaUi, form, iphoneUser, openFeed, postCard, publishPost, qaText, tap, type Published } from './post-helpers';

test.use({ ...IPHONE });

test.describe('מסך יצירת פוסט', () => {
  test('Пост free: у user4 в меню нет «עריכת הפוסט», прямая ссылка на редактирование закрыта @iphone @data (#1ff0f4)', async ({ browser, baseURL }) => {
    test.setTimeout(150_000);
    const free = await iphoneUser(browser, 'free', baseURL!);
    const user4 = await iphoneUser(browser, 'user4', baseURL!);
    const text = qaText('foreign');
    let published: Published | undefined;
    let deleted = false;
    try {
      // 1. free публикует пост
      published = await publishPost(free, text);

      // 2. user4 (та же аудитория) видит пост в ленте; в меню ⋯ нет редактирования/удаления
      await openFeed(user4);
      await expect(async () => {
        await user4.reload();
        await expect(user4.getByText(text, { exact: true })).toBeVisible({ timeout: 5_000 });
      }).toPass({ timeout: 45_000 });
      await tap(user4, postCard(user4, text).getByRole('button', { name: 'פעולות על הפוסט' }));
      const menu = user4.getByRole('dialog');
      await expect(menu.getByRole('button', { name: /דיווח על הפוסט/ })).toBeVisible();
      await expect(menu.getByRole('button', { name: /עריכת הפוסט/ })).toHaveCount(0);
      await expect(menu.getByRole('button', { name: /מחיקת הפוסט/ })).toHaveCount(0);
      await tap(user4, menu.getByRole('button', { name: 'ביטול' }));

      // 3. user4 открывает /post/new?id=<пост free> → редактирование запрещено (Р1.3)
      await user4.goto(`/post/new?id=${published.id}`);
      await expect(user4.getByText('אפשר לערוך רק פוסט שפרסמת')).toBeVisible();
      await expect(form(user4).text).toHaveCount(0);
      await expect(form(user4).save).toHaveCount(0);

      // 4. Очистка — автор удаляет пост
      await deletePostViaUi(free, text);
      deleted = true;
    } finally {
      if (published && !deleted) await cleanupPost(free, published);
      await saveSession(free, 'free');
      await saveSession(user4, 'user4');
      await free.context().close();
      await user4.context().close();
    }
  });
});
